plugins {
    id 'java'
    id 'application'
    id 'jacoco'
    id 'checkstyle'
    id 'org.openjfx.javafxplugin' version '0.1.0'
    id 'com.gradleup.shadow' version '9.6.1'
}

group = 'com.gymmie'
version = '1.0.0'

java {
    toolchain {
        languageVersion = JavaLanguageVersion.of(25)
    }
}

javafx {
    version = '25.0.1'
    modules = ['javafx.controls', 'javafx.fxml']
}

application {
    mainClass = 'com.gymmie.Launcher'
}

dependencies {
    testImplementation platform('org.junit:junit-bom:5.12.2')
    testImplementation 'org.junit.jupiter:junit-jupiter'
    testRuntimeOnly 'org.junit.platform:junit-platform-launcher'
}

test {
    useJUnitPlatform()
    finalizedBy jacocoTestReport
}

checkstyle {
    toolVersion = '10.26.1'
    configFile = file('config/checkstyle/checkstyle.xml')
    configProperties = [
        'checkstyle.suppressions.file': file('config/checkstyle/suppressions.xml').absolutePath
    ]
}

tasks.withType(Checkstyle).configureEach {
    exclude '**/module-info.java'
}

tasks.named('shadowJar') {
    archiveClassifier = ''
    manifest {
        attributes 'Main-Class': application.mainClass.get()
    }
}

tasks.named('build') {
    dependsOn tasks.named('shadowJar')
}

--- README ---
# Gymmie

Gymmie is a minimal JavaFX desktop app starter for gym and workout tracking.

## Build and run

Run `./gradlew run` to launch the app. Use `./gradlew check` for validation and
`./gradlew shadowJar` to build a runnable fat JAR.

