 68	    private void handleSave() {
 69	        String displayName = displayNameField.getText().trim();
 70	        String weeklyGoal = weeklyGoalField.getText().trim();
 71	
 72	        if (displayName.isEmpty()) {
 73	            showStatus("Please enter a display name.", false);
 74	            return;
 75	        }
 76	
 77	        try {
 78	            int goal = Integer.parseInt(weeklyGoal);
 79	            if (goal < 1 || goal > 14) {
 80	                showStatus("Weekly goal must be between 1 and 14 workouts.", false);
 81	                return;
 82	            }
 83	        } catch (NumberFormatException exception) {
 84	            showStatus("Weekly goal must be a whole number.", false);
 85	            return;
 86	        }
