 89	        preferences.put(WEEKLY_GOAL_KEY, weeklyGoal);
 90	        preferences.put(UNITS_KEY, unitsChoiceBox.getValue());
 91	        preferences.putBoolean(NOTIFICATIONS_KEY, notificationsCheckBox.isSelected());
 92	        preferences.putBoolean(REMINDERS_KEY, remindersCheckBox.isSelected());
 93	        showStatus("Settings saved.", true);
